import{_ as t,o as e,c as o,ai as r}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"分析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/analytics.md","filePath":"zh/guide/analytics.md"}'),n={name:"zh/guide/analytics.md"};function l(i,a,s,h,d,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="分析" tabindex="-1">分析 <a class="header-anchor" href="#分析" aria-label="Permalink to &quot;分析&quot;">​</a></h1><p>分析页深入呈现你的大模型使用模式、性能特征，以及回复质量随时间的变化。</p><p><strong>侧边栏位置：</strong> 分析 <strong>路由：</strong> <code>/analytics</code></p><h2 id="各个分区" tabindex="-1">各个分区 <a class="header-anchor" href="#各个分区" aria-label="Permalink to &quot;各个分区&quot;">​</a></h2><h3 id="回复质量" tabindex="-1">回复质量 <a class="header-anchor" href="#回复质量" aria-label="Permalink to &quot;回复质量&quot;">​</a></h3><p><strong>质量随轮次变化</strong>展示回复质量在多轮对话中的演变。每条助手回复按 0–5 分打分，依据是：</p><ul><li><strong>字数</strong>（权重 40%）—— 越长得分越高，上限为 50 词</li><li><strong>词汇多样性</strong>（权重 30%）—— 不重复词数与总词数之比</li><li><strong>低重复度</strong>（权重 30%）—— 4-gram 重复越少得分越高</li></ul><p>数据点按颜色区分：绿色（3.5 以上）、黄色（2–3.5）、红色（低于 2）。</p><h3 id="延迟分析" tabindex="-1">延迟分析 <a class="header-anchor" href="#延迟分析" aria-label="Permalink to &quot;延迟分析&quot;">​</a></h3><p>三张分析请求性能的图表：</p><ul><li><strong>请求延迟 P50/P95/P99</strong> —— 会话中 <code>totalDurationMs</code> 的滑动窗口百分位</li><li><strong>TTFT P50/P95/P99</strong> —— 对首 token 时间做同样的处理</li><li><strong>token 间延迟分布</strong> —— token 与 token 之间耗时的直方图，采用 OpenTelemetry 推荐的分桶边界</li></ul><h3 id="可靠性" tabindex="-1">可靠性 <a class="header-anchor" href="#可靠性" aria-label="Permalink to &quot;可靠性&quot;">​</a></h3><ul><li><strong>各模型错误率</strong> —— 堆叠柱状图，按模型显示各类错误</li><li><strong>错误时间线</strong> —— 每日错误数量随时间的变化</li><li><strong>加载耗时趋势</strong> —— 模型加载时间，并标出冷启动（超过 500ms 时显示橙色点）</li></ul><p>错误类别包括：连接、超时、模型未找到、超出上下文、内存不足、工具错误、已取消。</p><h3 id="使用模式" tabindex="-1">使用模式 <a class="header-anchor" href="#使用模式" aria-label="Permalink to &quot;使用模式&quot;">​</a></h3><ul><li><strong>请求量</strong> —— 每日请求数量的柱状图</li><li><strong>模型分布</strong> —— 环形图，显示各模型请求量的占比</li><li><strong>活跃时段热力图</strong> —— 7 天 × 24 小时的网格，按请求密度着色</li></ul><h3 id="设置的影响" tabindex="-1">设置的影响 <a class="header-anchor" href="#设置的影响" aria-label="Permalink to &quot;设置的影响&quot;">​</a></h3><p>一张散点图，显示温度与 token/秒之间的相关性。每个点代表一次会话。需要至少 2 次明确设置了温度的会话。</p><h3 id="模型内存" tabindex="-1">模型内存 <a class="header-anchor" href="#模型内存" aria-label="Permalink to &quot;模型内存&quot;">​</a></h3><p>近期模型加载事件的时间线，显示加载耗时以及冷启动 / 热启动状态。冷启动（超过 500ms）以橙色高亮。</p><h2 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h2><p>所有分析都在客户端计算，数据来自已经存储在 IndexedDB 中的 <code>SessionMetrics</code>。不需要额外采集任何数据。有新会话记录时，图表会响应式地自动更新。</p>',22)])])}const p=t(n,[["render",l]]);export{u as __pageData,p as default};
